import from .store { get_session, ParsedSession, TrajectoryNode, SubagentRef }
import from .TrajectoryGraph { TrajectoryGraph }
import from .NodeDetailModal { NodeDetailModal }
import from .treeUtils { findNode }
import from "..components.ui.toggle" { Toggle }
import from "..components.ui.badge" { Badge }
import from "..components.ui.skeleton" { Skeleton }

obj ViewFrame {
    has label: str;
    has session: ParsedSession;
}

def:pub TrajectoryShell(filePath: str) -> JsxElement {
    has viewStack: list[ViewFrame] = [];
    has loading: bool = True;
    has loadError: str = "";
    has showSystem: bool = False;
    has selectedNodeId: str | None = None;
    has modalOpen: bool = False;

    async can with [filePath] entry {
        loading = True;
        loadError = "";
        try {
            parsed = await get_session(filePath);
            label = parsed.ai_title if parsed.ai_title else parsed.session_id;
            viewStack = [ViewFrame(label=label, session=parsed)];
        } except Exception as e {
            loadError = str(e);
        }
        loading = False;
    }

    def handle_select_node(nodeId: str) {
        selectedNodeId = nodeId;
        modalOpen = True;
    }

    def handle_modal_open_change(next: bool) {
        modalOpen = next;
    }

    async def handle_open_subagent(ref: SubagentRef) -> None {
        loading = True;
        try {
            parsed = await get_session(ref.file_path);
            label = ref.description if len(ref.description) > 0 else ref.agent_id;
            viewStack = viewStack + [ViewFrame(label=label, session=parsed)];
            modalOpen = False;
        } except Exception as e {
            loadError = str(e);
        }
        loading = False;
    }

    def handle_breadcrumb_click(index: int) {
        viewStack = viewStack[0:index + 1];
        modalOpen = False;
    }

    def handle_toggle_system(pressed: bool) {
        showSystem = pressed;
    }

    if loading {
        return <div className="flex flex-col gap-3 p-6">
            <Skeleton className="h-8 w-1/3" />
            <Skeleton className="h-[60vh] w-full" />
        </div>;
    }

    if len(loadError) > 0 or len(viewStack) == 0 {
        return <div className="p-6 text-sm text-destructive">
            Failed to load session: {loadError if len(loadError) > 0 else "unknown error"}
        </div>;
    }

    current = viewStack[len(viewStack) - 1];
    subagentByNodeId: dict = {};
    for ref in current.session.subagents {
        subagentByNodeId[ref.spawn_node_id] = ref;
    }
    selectedNode: TrajectoryNode | None = None;
    if selectedNodeId is not None {
        selectedNode = findNode(current.session.main_trajectory, selectedNodeId);
    }

    <div className="flex h-screen flex-col">
        <div className="flex items-center justify-between border-b px-4 py-2">
            <div className="flex items-center gap-2 overflow-x-auto text-sm">
                {for (i, frame) in enumerate(viewStack) {
                    <span key={str(i)} className="flex items-center gap-2">
                        {i > 0 and <span className="text-muted-foreground">/</span>}
                        <button
                            className={"hover:underline " + ("font-semibold" if i == len(viewStack) - 1 else "text-muted-foreground")}
                            onClick={lambda { handle_breadcrumb_click(i); }}
                        >
                            {frame.label}
                        </button>
                    </span>
                }}
            </div>
            <div className="flex items-center gap-3">
                <Badge variant="outline">{str(current.session.stats.message_count)} messages</Badge>
                <Badge variant="outline">{str(current.session.stats.tool_call_count)} tool calls</Badge>
                <Toggle pressed={showSystem} onPressedChange={handle_toggle_system}>
                    Show system events
                </Toggle>
            </div>
        </div>

        <div className="min-h-0 flex-1">
            <TrajectoryGraph
                treeRoot={current.session.main_trajectory}
                showSystem={showSystem}
                onSelectNode={handle_select_node}
            />
        </div>

        <NodeDetailModal
            targetNode={selectedNode}
            open={modalOpen}
            onOpenChange={handle_modal_open_change}
            subagentByNodeId={subagentByNodeId}
            onOpenSubagent={handle_open_subagent}
        />
    </div>
}
